#!/usr/bin/env python3
"""Regenerate agent-tools.txt, the hash-locked test tools baked into the agent image.

The sandbox blocks public registries, so an agent can only run tools that are
already in its image (red-team #12). This resolves the exact pins in
agent-tools.in inside the agent image's Python base, then writes every wheel's
SHA-256 for linux x86_64 and aarch64 from PyPI, so the image build can install
with --require-hashes on either architecture.

    python3 sandbox/docker/lock_agent_tools.py

Needs Docker and network access on the machine that runs it, not in the sandbox.
"""
import json
import os
import re
import subprocess
import sys
import urllib.request

HERE = os.path.dirname(os.path.abspath(__file__))
SOURCE = os.path.join(HERE, "agent-tools.in")
LOCK = os.path.join(HERE, "agent-tools.txt")
DOCKERFILE = os.path.join(HERE, "agent.Dockerfile")
PYTHON_TAG = "cp312"
ARCHES = ("x86_64", "aarch64")


def base_python_image():
    with open(DOCKERFILE, encoding="utf-8") as handle:
        match = re.search(r"^FROM (python:[^\s]+@sha256:[0-9a-f]{64})", handle.read(), re.MULTILINE)
    if not match:
        sys.exit("agent.Dockerfile has no digest-pinned python base image")
    return match.group(1)


def top_level_pins():
    pins = []
    with open(SOURCE, encoding="utf-8") as handle:
        for line in handle:
            line = line.split("#", 1)[0].strip()
            if not line:
                continue
            if not re.fullmatch(r"[A-Za-z0-9_.\-]+==[A-Za-z0-9_.\-]+", line):
                sys.exit(f"agent-tools.in: pin an exact version, got {line!r}")
            pins.append(line)
    return pins


def resolve(image, pins):
    """Return [(name, version)] for the pins and all their dependencies."""
    command = ["docker", "run", "--rm", image, "pip", "install", "--disable-pip-version-check",
               "--dry-run", "--quiet", "--ignore-installed", "--only-binary=:all:", "--report", "-"] + pins
    result = subprocess.run(command, capture_output=True, text=True, check=False)
    if result.returncode:
        sys.exit("resolving failed:\n" + result.stderr)
    report = json.loads(result.stdout)
    return sorted((item["metadata"]["name"].lower(), item["metadata"]["version"])
                  for item in report["install"])


def wheel_fits(filename):
    """True for a wheel that installs on CPython 3.12 under glibc on x86_64 or aarch64."""
    tags = filename[:-len(".whl")].split("-")[-3:]
    python, abi, platform = tags
    if not set(python.split(".")) & {PYTHON_TAG, "py3", "py2.py3"} and "abi3" not in abi:
        return False
    if platform == "any":
        return True
    return any(p.startswith("manylinux") and p.endswith(arch)
               for p in platform.split(".") for arch in ARCHES)


def hashes(name, version):
    url = f"https://pypi.org/pypi/{name}/{version}/json"
    with urllib.request.urlopen(url, timeout=60) as response:
        files = json.load(response)["urls"]
    found = sorted(f["digests"]["sha256"] for f in files
                   if f["packagetype"] == "bdist_wheel" and wheel_fits(f["filename"]))
    if not found:
        sys.exit(f"no linux wheel for {name}=={version}")
    return found


def main():
    pins = top_level_pins()
    lines = ["# Generated by lock_agent_tools.py from agent-tools.in. Don't edit by hand.",
             "# Installed with --require-hashes --no-deps --only-binary=:all: in agent.Dockerfile."]
    for name, version in resolve(base_python_image(), pins):
        entry = [f"{name}=={version}"]
        entry += ["    --hash=sha256:" + digest for digest in hashes(name, version)]
        lines.append(" \\\n".join(entry))
    with open(LOCK, "w", encoding="utf-8") as handle:
        handle.write("\n".join(lines) + "\n")
    print("wrote", os.path.relpath(LOCK))


if __name__ == "__main__":
    main()
